import{_ as e,o as t,c as i,ag as l}from"./chunks/framework.DyxC4IQh.js";const m=JSON.parse('{"title":"安装","description":"装 APK 与打开系统开关是两步，装完为什么还不能直接用。","frontmatter":{"description":"装 APK 与打开系统开关是两步，装完为什么还不能直接用。"},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md","lastUpdated":1792203326000}'),d={name:"guide/install.md"};function o(c,a,r,s,n,h){return t(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="安装" tabindex="-1">安装 <a class="header-anchor" href="#安装" aria-label="Permalink to &quot;安装&quot;">​</a></h1><p>VimAct 是一个 APK，加一个必须手动打开的系统开关。装完不等于能用了，两件事得分开做。</p><h2 id="前提" tabindex="-1">前提 <a class="header-anchor" href="#前提" aria-label="Permalink to &quot;前提&quot;">​</a></h2><ul><li>Android 10（API 29）或更高。这个数字是构建里定的下限，图的是主流设备覆盖；按键过滤本身从 API 18 就具备，不是它卡住了版本。低于 29 的设备，安装器会直接拒绝这个包。</li><li>一把物理键盘：蓝牙、USB、平板或折叠屏的内置键盘都算。纯触屏手机用不上这个工具。</li><li>允许侧载。软件当前不在应用商店，来源见<a href="/vimact-site/download.html">下载</a>。</li></ul><h2 id="装-apk" tabindex="-1">装 APK <a class="header-anchor" href="#装-apk" aria-label="Permalink to &quot;装 APK&quot;">​</a></h2><p>从<a href="/vimact-site/download.html">下载</a>取一个 APK，用文件管理器打开并安装。系统会要求你确认「允许来自此来源的应用」，一次性授权即可。</p><p>安装本身不会让 VimAct 开始工作。它此刻只是躺在系统里，没有拿到任何读取屏幕的能力。</p><h2 id="打开无障碍服务" tabindex="-1">打开无障碍服务 <a class="header-anchor" href="#打开无障碍服务" aria-label="Permalink to &quot;打开无障碍服务&quot;">​</a></h2><p>这是必需的一步，原因见<a href="/vimact-site/guide/accessibility.html">启用无障碍服务</a>。</p><p>最快的路径是启动 VimAct，主页点「Open accessibility settings」，系统会打开无障碍设置页，在里面找到 VimAct 打开即可。</p><p>打开之后回到 VimAct 主页，顶部那行状态文字应当变成 <code>Status: enabled</code>。如果还是 <code>disabled</code>，说明开关没落到系统里，常见原因是 ROM 需要多确认一层授权弹窗。</p><h2 id="试一下" tabindex="-1">试一下 <a class="header-anchor" href="#试一下" aria-label="Permalink to &quot;试一下&quot;">​</a></h2><p>切到任意 App，按一下 <code>F</code>。屏幕上的可点击元素左上角应该弹出黄色小标签。</p><p>第一次按 <code>F</code> 没有任何反应，通常是这几个原因：状态行还是 <code>disabled</code>；当前 App 被加进了<a href="/vimact-site/guide/settings.html">排除列表</a>；输入法正弹着（此时 VimAct 会让路，见<a href="/vimact-site/guide/faq.html">常见问题</a>）。还有一种最容易漏：状态行显示 <code>enabled</code>、服务进程却被 ROM 冻结或杀掉了——主页那行状态读的是系统设置里的开关值，开关开着它就写 enabled，进程死不死它不知道。按<a href="/vimact-site/guide/accessibility.html">启用无障碍服务</a>里的三条 ROM 排查走。</p><h2 id="卸载" tabindex="-1">卸载 <a class="header-anchor" href="#卸载" aria-label="Permalink to &quot;卸载&quot;">​</a></h2><p>先在系统无障碍设置里关掉 VimAct 的服务开关，再卸载 APK。顺序反过来也不会留下残余，无障碍服务随应用一起消失，但先关服务能让你确认卸载前它已经停止介入。</p>',16)])])}const u=e(d,[["render",o]]);export{m as __pageData,u as default};
